-- ============================================================================
-- WDOS Migration 141 — Monday-only display + French weekly inspiration
-- (Phase 187)
--   1. my_hq_message() now returns the card ONLY on a Monday, as instructed.
--      The rest of the week it lives in My Messages. Also resolves the
--      leader's language: her preferred_locale version if it exists, English
--      otherwise (framework §14).
--   2. French content for all 13 weeks, both networks, plus the 20
--      role-specific ACT inserts.
-- ============================================================================

  body, key_thought, closing, tagline, graphic_slug, status)
 values ('WODDI-WI-001', 'WGMN', 'fr', 1, 1, 1, 'Identity and Purpose', 'Vous Faites Partie de Quelque Chose de Plus Grand que Vous', 'Les femmes enracinées dirigent avec détermination et fortifient les autres par leur exemple.',
  'En tant que {{RoleTitle}} à {{LocationName}}, votre leadership WGMN pose une fondation d''identité, de raison d''être et de service fiable. Votre leadership atteint les femmes, les familles et les communautés à travers les choix que vous posez chaque jour. Le thème de cette semaine, « Vous Faites Partie de Quelque Chose de Plus Grand que Vous », vous invite à transformer votre expérience en un exemple auquel les autres peuvent se fier. Appliquez-le avec sagesse, dignité et un suivi constant. Lorsqu''une femme dirige avec responsabilité, elle rend le chemin plus facile aux autres femmes qui veulent grandir, contribuer et fortifier leur entourage.', 'Les femmes enracinées dirigent avec détermination et fortifient les autres par leur exemple.', 'Merci de diriger WGMN avec détermination et bienveillance.', 'WGMN — Accompagner les femmes, fortifier les familles.', 'wi001-wgmn', 'approved')
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
       graphic_key_thought = excluded.graphic_key_thought, closing = excluded.closing, tagline = excluded.tagline;
  body, key_thought, closing, tagline, graphic_slug, status)
 values ('WODDI-WI-001', 'WNNN', 'fr', 1, 1, 1, 'Identity and Purpose', 'Vous Êtes la Prochaine Génération de Femmes Leaders', 'Vous n''attendez pas de devenir leader ; vous apprenez déjà à diriger avec responsabilité.',
  'En tant que {{RoleTitle}} à {{LocationName}}, votre leadership WNNN fortifie les jeunes femmes dans leur identité, leur voix et leurs valeurs. Vous n''avez pas besoin d''attendre un titre futur ni le moment parfait pour bien diriger. Le thème de cette semaine, « Vous Êtes la Prochaine Génération de Femmes Leaders », peut façonner les choix que vous posez dès maintenant dans vos études, votre travail, votre service et vos relations. Faites un pas responsable, apprenez-en quelque chose et continuez à grandir. Votre exemple peut aider une autre jeune femme à croire que sa voix, ses valeurs et sa contribution comptent.', 'Vous n''attendez pas de devenir leader ; vous apprenez déjà à diriger avec responsabilité.', 'Merci de diriger WNNN avec détermination et bienveillance.', 'WNNN — Élever la prochaine génération de femmes leaders.', 'wi001-wnnn', 'approved')
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
       graphic_key_thought = excluded.graphic_key_thought, closing = excluded.closing, tagline = excluded.tagline;
  body, key_thought, closing, tagline, graphic_slug, status)
 values ('WODDI-WI-002', 'WGMN', 'fr', 1, 1, 2, 'Identity and Purpose', 'Le Leadership Commence par le Cœur', 'L''attention et la redevabilité réunies créent un leadership digne de confiance.',
  'En tant que {{RoleTitle}} à {{LocationName}}, votre leadership WGMN pose une fondation d''identité, de raison d''être et de service fiable. Le leadership mûr se voit dans la manière dont nous tenons ensemble la raison d''être, les personnes et la responsabilité. En méditant « Le Leadership Commence par le Cœur », regardez la part du réseau qui vous est confiée. Choisissez la réponse qui protège la dignité, renforce la confiance et fait avancer le travail. Un service constant, offert sans pression inutile, bâtit une confiance qui dure.', 'L''attention et la redevabilité réunies créent un leadership digne de confiance.', 'Merci de diriger WGMN avec détermination et bienveillance.', 'WGMN — Accompagner les femmes, fortifier les familles.', 'wi002-wgmn', 'approved')
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
       graphic_key_thought = excluded.graphic_key_thought, closing = excluded.closing, tagline = excluded.tagline;
  body, key_thought, closing, tagline, graphic_slug, status)
 values ('WODDI-WI-002', 'WNNN', 'fr', 1, 1, 2, 'Identity and Purpose', 'Votre Raison d''Être Est Plus Grande que Votre Peur', 'Votre voix se renforce lorsqu''elle est guidée par les valeurs et par l''action.',
  'En tant que {{RoleTitle}} à {{LocationName}}, votre leadership WNNN fortifie les jeunes femmes dans leur identité, leur voix et leurs valeurs. WNNN est un espace où les jeunes femmes découvrent leur raison d''être, pratiquent le leadership et grandissent sans faire semblant de tout savoir. En méditant « Votre Raison d''Être Est Plus Grande que Votre Peur », restez ouverte à l''apprentissage et aux retours honnêtes. La confiance n''est pas d''avoir toutes les réponses ; c''est d''accepter d''agir avec responsabilité, de demander du soutien et de progresser à chaque expérience.', 'Votre voix se renforce lorsqu''elle est guidée par les valeurs et par l''action.', 'Merci de diriger WNNN avec détermination et bienveillance.', 'WNNN — Élever la prochaine génération de femmes leaders.', 'wi002-wnnn', 'approved')
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
       graphic_key_thought = excluded.graphic_key_thought, closing = excluded.closing, tagline = excluded.tagline;
  body, key_thought, closing, tagline, graphic_slug, status)
 values ('WODDI-WI-003', 'WGMN', 'fr', 1, 1, 3, 'Identity and Purpose', 'Servir avec Détermination, Sans Pression', 'L''expérience prend de la valeur lorsqu''elle sert à élever une autre femme.',
  'En tant que {{RoleTitle}} à {{LocationName}}, votre leadership WGMN pose une fondation d''identité, de raison d''être et de service fiable. L''esprit de la Bonne Mère s''exprime par une influence porteuse de sens, et non par le titre seul. Le message « Servir avec Détermination, Sans Pression » doit se voir dans votre manière de communiquer, d''accompagner, d''organiser et d''assurer le suivi. Votre exemple peut aider une autre femme à s''enraciner davantage dans son identité, à gagner en assurance et à agir avec plus d''intention pour sa famille et sa communauté.', 'L''expérience prend de la valeur lorsqu''elle sert à élever une autre femme.', 'Merci de diriger WGMN avec détermination et bienveillance.', 'WGMN — Accompagner les femmes, fortifier les familles.', 'wi003-wgmn', 'approved')
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
       graphic_key_thought = excluded.graphic_key_thought, closing = excluded.closing, tagline = excluded.tagline;
  body, key_thought, closing, tagline, graphic_slug, status)
 values ('WODDI-WI-003', 'WNNN', 'fr', 1, 1, 3, 'Identity and Purpose', 'Le Leadership Commence par Savoir Qui Vous Êtes', 'La confiance se construit par la responsabilité, la réflexion et la pratique.',
  'En tant que {{RoleTitle}} à {{LocationName}}, votre leadership WNNN fortifie les jeunes femmes dans leur identité, leur voix et leurs valeurs. Votre génération influence déjà les communautés, en ligne comme hors ligne. Le message « Le Leadership Commence par Savoir Qui Vous Êtes » vous invite à user de cette influence avec des valeurs, de l''attention et du discernement. Que vos paroles créent la sécurité, que vos actes bâtissent la confiance et que votre présence numérique reflète la leader que vous devenez.', 'La confiance se construit par la responsabilité, la réflexion et la pratique.', 'Merci de diriger WNNN avec détermination et bienveillance.', 'WNNN — Élever la prochaine génération de femmes leaders.', 'wi003-wnnn', 'approved')
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
       graphic_key_thought = excluded.graphic_key_thought, closing = excluded.closing, tagline = excluded.tagline;
  body, key_thought, closing, tagline, graphic_slug, status)
 values ('WODDI-WI-004', 'WGMN', 'fr', 1, 1, 4, 'Identity and Purpose', 'La Force de la Présence Constante', 'Un service sain protège à la fois la mission et la femme qui sert.',
  'En tant que {{RoleTitle}} à {{LocationName}}, votre leadership WGMN pose une fondation d''identité, de raison d''être et de service fiable. Les femmes portent souvent plusieurs responsabilités à la fois ; un leadership réfléchi est donc essentiel. Que « La Force de la Présence Constante » vous aide à distinguer ce qui mérite votre attention maintenant, ce qui peut être délégué et ce qui doit absolument être mené à terme. Une action claire et mesurée protège votre bien-être tout en fortifiant les femmes et les leaders qui comptent sur vous.', 'Un service sain protège à la fois la mission et la femme qui sert.', 'Merci de diriger WGMN avec détermination et bienveillance.', 'WGMN — Accompagner les femmes, fortifier les familles.', 'wi004-wgmn', 'approved')
 on conflict (message_id, network, language, version) do update
