  body, key_thought, closing, tagline, graphic_slug, status)
 values ('WODDI-WI-007', 'WNNN', 'fr', 1, 1, 7, 'Identity and Purpose', 'La Confiance Grandit Quand Vous Prenez des Responsabilités', 'Votre progression peut ouvrir la voie à une autre jeune femme.',
  'En tant que {{RoleTitle}} à {{LocationName}}, votre leadership WNNN fortifie les jeunes femmes dans leur identité, leur voix et leurs valeurs. Partout en Afrique, de jeunes femmes apportent au leadership des idées neuves et de l''énergie. En vous concentrant sur « La Confiance Grandit Quand Vous Prenez des Responsabilités », rappelez-vous que l''innovation exige aussi de la discipline, de la protection et du respect. Servez-vous de votre créativité pour résoudre un problème réel, écoutez les personnes concernées et tenez l''engagement que vous prenez.', 'Votre progression peut ouvrir la voie à une autre jeune femme.', 'Merci de diriger WNNN avec détermination et bienveillance.', 'WNNN — Élever la prochaine génération de femmes leaders.', 'wi007-wnnn', 'approved')
 on conflict (message_id, network, language, version) do update
   set headline = excluded.headline, body = excluded.body, key_thought = excluded.key_thought,
