alter table public.hq_message_inserts add column if not exists language text not null default 'en';
alter table public.hq_message_inserts drop constraint if exists hq_message_inserts_message_id_network_role_key;
create unique index if not exists hq_inserts_uq on public.hq_message_inserts (message_id, network, role, language);

-- ---------------------------------------------------------------------------
-- Monday only, and in her language.
-- ---------------------------------------------------------------------------
drop function if exists public.my_hq_message(boolean);
create or replace function public.my_hq_message(p_record boolean default true, p_any_day boolean default false)
returns jsonb language plpgsql
security definer set search_path = public as $$
declare
  me uuid := auth.uid();
  p profiles%rowtype;
  seat record;
  net text; role_code text; role_title text; loc text; lang text;
  wk int; monday date; is_monday boolean;
  m hq_messages%rowtype; ins text; out_body text;
begin
  if me is null then return null; end if;
  select * into p from profiles where id = me;
  if not found then return null; end if;

  -- Azeez, 13 Sep 2026: the card appears on MONDAY only. For the rest of the
  -- week the message is still hers, in My Messages, but the dashboard is clear.
  is_monday := extract(isodow from current_date) = 1;
  if not is_monday and not coalesce(p_any_day, false) then return null; end if;

  select ra.role::text as role, ou.name as unit_name into seat
    from role_assignments ra join org_units ou on ou.id = ra.org_unit_id
   where ra.profile_id = me and ra.ends_at is null
   order by case ra.role::text when 'country_rep' then 1 when 'deputy_country_rep' then 2 else 3 end
   limit 1;

  net := coalesce(p.network::text, 'WGMN');
  role_code := coalesce(seat.role, '');
  lang := coalesce(nullif(p.preferred_locale, ''), 'en');
  role_title := coalesce(public.role_title(role_code, net), p.role_applied, 'volunteer leader');
  loc := coalesce(seat.unit_name, p.state_region, p.country, '');

  monday := (current_date - ((extract(isodow from current_date)::int - 1)))::date;
  wk := least(13, greatest(1, ((monday - date '2026-09-14') / 7)::int + 1));
  if monday < date '2026-09-14' then wk := 1; end if;

  -- her language if an approved translation exists, English otherwise
  select * into m from hq_messages
   where network = net and week_no = wk and year_no = 1
     and status in ('approved','scheduled','published')
     and language = lang
   order by version desc limit 1;
  if not found then
    select * into m from hq_messages
     where network = net and week_no = wk and year_no = 1
       and status in ('approved','scheduled','published') and language = 'en'
     order by version desc limit 1;
    lang := 'en';
  end if;
  if not found then return null; end if;

  select insert_text into ins from hq_message_inserts
   where message_id = m.message_id and network = net and role = role_code and language = lang;
  if ins is null then
    select insert_text into ins from hq_message_inserts
     where message_id = m.message_id and network = net and role = role_code and language = 'en';
  end if;

  out_body := replace(replace(replace(m.body,
      '{{FirstName}}', p.first_name), '{{RoleTitle}}', role_title), '{{LocationName}}', loc);

  if p_record then
    values (me, m.message_id, net, m.version)
    on conflict (profile_id, message_id, version, channel) do nothing;
  end if;

  return jsonb_build_object(
    'message_id', m.message_id, 'category', m.category, 'network', net, 'language', lang,
    'week_no', m.week_no, 'theme', m.theme, 'week_of', to_char(monday, 'DD/MM/YYYY'),
    'greeting', case when lang = 'fr' then 'Chère ' || p.first_name || ',' else 'Dear ' || p.first_name || ',' end,
    'first_name', p.first_name, 'role_title', role_title, 'location', loc,
    'headline', m.headline, 'body', out_body, 'key_thought', m.key_thought,
    'act', ins, 'closing', m.closing, 'signature', m.signature, 'tagline', m.tagline,
    'graphic', '/assets/hq-messages/' || m.graphic_slug || '.svg',
    'released_on', monday);
end; $$;
revoke execute on function public.my_hq_message(boolean, boolean) from anon;

-- The archive must not be Monday-gated, and must follow her language too.
create or replace function public.my_hq_message_archive(p_limit int default 30)
returns jsonb language sql stable security definer set search_path = public as $$
  with meq as (select * from profiles where id = auth.uid())
  select coalesce(jsonb_agg(x order by x->>'displayed_at' desc), '[]'::jsonb) from (
    select jsonb_build_object(
      'message_id', d.message_id, 'network', d.network, 'week_no', m.week_no,
      'headline', m.headline, 'theme', m.theme, 'key_thought', m.key_thought,
      'body', replace(replace(replace(m.body, '{{FirstName}}', (select first_name from meq)),
                '{{RoleTitle}}', coalesce(public.role_title((select ra.role::text from role_assignments ra
                    where ra.profile_id = auth.uid() and ra.ends_at is null limit 1), d.network), 'volunteer leader')),
                '{{LocationName}}', coalesce((select state_region from meq), (select country from meq), '')),
      'graphic', '/assets/hq-messages/' || m.graphic_slug || '.svg',
      'displayed_at', d.displayed_at, 'read_at', d.read_at) as x
      from hq_message_delivery d
      join hq_messages m on m.message_id = d.message_id and m.network = d.network
       and m.language = coalesce(nullif((select preferred_locale from meq), ''), 'en')
     where d.profile_id = auth.uid()
     order by d.displayed_at desc
     limit greatest(1, least(100, p_limit))) s;
$$;
revoke execute on function public.my_hq_message_archive(int) from anon;

values (141, 'monday_only_and_french') on conflict (version) do nothing;
