insert into public.hq_message_inserts (message_id, network, role, language, insert_text) values ('WODDI-WI-001', 'WGMN', 'country_rep', 'fr', 'AGIR : Fixez une priorité nationale sur le thème de la semaine ; alignez la Adjointe et les leaders infranationales ; vérifiez son effet sur les femmes, les familles ou les communautés.') on conflict (message_id, network, role, language) do update set insert_text = excluded.insert_text;
insert into public.hq_message_inserts (message_id, network, role, language, insert_text) values ('WODDI-WI-001', 'WGMN', 'deputy_country_rep', 'fr', 'AGIR : Coordonnez le suivi délégué du thème de la semaine ; comblez une lacune nationale et rendez compte à la Représentante Pays.') on conflict (message_id, network, role, language) do update set insert_text = excluded.insert_text;
insert into public.hq_message_inserts (message_id, network, role, language, insert_text) values ('WODDI-WI-001', 'WGMN', 'state_coordinator', 'fr', 'AGIR : Appliquez le thème de la semaine par une action au niveau de l''État ou de la région ; informez les coordinatrices locales concernées et vérifiez l''exécution dans WDOS.') on conflict (message_id, network, role, language) do update set insert_text = excluded.insert_text;
insert into public.hq_message_inserts (message_id, network, role, language, insert_text) values ('WODDI-WI-001', 'WGMN', 'assistant_state_coordinator', 'fr', 'AGIR : Réalisez un suivi délégué par écrit sur le thème de la semaine ; rendez compte à la Coordinatrice et n''exercez aucune autorité régionale indépendante.') on conflict (message_id, network, role, language) do update set insert_text = excluded.insert_text;
insert into public.hq_message_inserts (message_id, network, role, language, insert_text) values ('WODDI-WI-001', 'WGMN', 'district_coordinator', 'fr', 'AGIR : Répondez à un besoin local à travers le thème de la semaine ; guidez les coordinatrices communautaires concernées et consignez le résultat dans WDOS.') on conflict (message_id, network, role, language) do update set insert_text = excluded.insert_text;
insert into public.hq_message_inserts (message_id, network, role, language, insert_text) values ('WODDI-WI-001', 'WGMN', 'assistant_district_coordinator', 'fr', 'AGIR : Réalisez un suivi local délégué par écrit sur le thème de la semaine ; rendez compte par la Coordinatrice et n''émettez aucune instruction générale.') on conflict (message_id, network, role, language) do update set insert_text = excluded.insert_text;
insert into public.hq_message_inserts (message_id, network, role, language, insert_text) values ('WODDI-WI-001', 'WGMN', 'cluster_coordinator', 'fr', 'AGIR : Utilisez le thème de la semaine pour renforcer un lien communautaire, une activité ou une lacune de leadership, en incluant les femmes avec dignité.') on conflict (message_id, network, role, language) do update set insert_text = excluded.insert_text;
insert into public.hq_message_inserts (message_id, network, role, language, insert_text) values ('WODDI-WI-001', 'WGMN', 'assistant_cluster_coordinator', 'fr', 'AGIR : Réalisez un suivi communautaire qui vous est confié sur le thème de la semaine ; soutenez la Coordinatrice et restez dans le cadre de la délégation écrite.') on conflict (message_id, network, role, language) do update set insert_text = excluded.insert_text;
